const tools=await fetch('./catalog.json?v=4').then(r=>{if(!r.ok)throw Error('目录暂时无法读取');return r.json()});
const search=document.querySelector('#search'),filters=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.tool-card')],count=document.querySelector('#result-count'),empty=document.querySelector('#empty');
let active='all';
function filter(){const q=search.value.trim().toLocaleLowerCase();let visible=0;for(const c of cards){const t=tools.find(t=>t.id===c.dataset.id);const platform=active==='all'||(active==='web'?!!t.web:!!t.download||t.id==='harbor');const found=[t.name,t.en,t.description,t.category,...t.features].join(' ').toLocaleLowerCase().includes(q);c.hidden=!(platform&&found);if(!c.hidden)visible++;}count.textContent=`${visible} 件工具`;empty.hidden=visible!==0;}
filters.forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;filters.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter();}));search.addEventListener('input',filter);
document.querySelector('#reset').addEventListener('click',()=>{search.value='';active='all';filters.forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter==='all')));filter();search.focus();});
const dialog=document.querySelector('#details');let opener;
function fill(id,button){const t=tools.find(x=>x.id===id);if(!t)return;opener=button;dialog.querySelector('#detail-name').textContent=t.name;dialog.querySelector('#detail-en').textContent=t.en;dialog.querySelector('#detail-description').textContent=t.description;dialog.querySelector('#detail-platform').textContent=t.platform;dialog.querySelector('#detail-note').textContent=t.note;for(const [selector,items] of [['#detail-features',t.features],['#detail-steps',t.steps]]){const list=dialog.querySelector(selector);list.replaceChildren(...items.map(s=>{const li=document.createElement('li');li.textContent=s;return li;}));}const actions=dialog.querySelector('#detail-actions');actions.replaceChildren();for(const [url,label,download] of [[t.web,'在线打开 ↗',false],[t.download,'下载 Mac 版 ↓',true],[t.source,'下载源码 ↓',true]]){if(!url)continue;const a=document.createElement('a');a.href=url;a.textContent=label;a.className='button '+(download?'button-light':'button-red');if(download)a.download='';else{a.target='_blank';a.rel='noopener noreferrer';}actions.append(a);}if(!actions.children.length){const p=document.createElement('p');p.className='local-note';p.textContent='目前为本机版 · 安装包暂未上架';actions.append(p);}dialog.showModal();}
document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>fill(b.dataset.detail,b)));
dialog.querySelector('#close-details').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>opener?.focus());
filter();
